ON CONFLICT (id) DO UPDATE SET
  cliente_id = EXCLUDED.cliente_id,
  campo_id = EXCLUDED.campo_id,
  pluviometro_id = EXCLUDED.pluviometro_id,
  usuario_email = EXCLUDED.usuario_email,
  fecha = EXCLUDED.fecha,
  pluviometro_nombre = EXCLUDED.pluviometro_nombre,
  milimetros = EXCLUDED.milimetros;

COMMIT;

-- Verificación exacta de la importación.
SELECT
  COUNT(*) AS mediciones,
  MIN(fecha) AS desde,
  MAX(fecha) AS hasta,
  SUM(milimetros) AS mm_total
FROM lluvias
WHERE cliente_id = 'el-renuevo'
  AND id LIKE 'lluvia-el-renuevo-%';

SELECT p.nombre AS pluviometro, c.nombre AS campo,
       COUNT(l.id) AS mediciones, SUM(l.milimetros) AS mm_total
FROM pluviometros p
JOIN campos c ON c.id = p.campo_id
LEFT JOIN lluvias l ON l.pluviometro_id = p.id AND l.cliente_id = p.cliente_id
WHERE p.cliente_id = 'el-renuevo'
GROUP BY p.id, p.nombre, c.nombre
ORDER BY c.nombre, p.nombre;
